class ScopeGuard {
    // Automatic object registered for destruction
public:
    ScopeGuard() {}
    ~ScopeGuard() { /* Destructor is called during unwind */ }
};

void deep_func() {
    ScopeGuard G_deep;
    // Exception tables track G_deep's address and destructor
    throw 42;
}

void main_func() {
    ScopeGuard G_main;
    try {
        deep_func();
    } catch (int e) {
        // Handled: G_deep and G_main destructors already called
    }
}
